import numpy as np
import pickle
import os
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from sklearn.mixture import GaussianMixture
from sklearn.metrics import roc_curve
from scipy.stats import gaussian_kde

# Path to the data generated by evaluate_Gait3D
pkl_file = "roc_data/embeddings_Gait3D_DeepGaitV2_triplet_margin0.2.pkl"

if not os.path.exists(pkl_file):
    print(f"Error: {pkl_file} not found. Please run the evaluation first.")
    exit(1)

print(f"Loading data from {pkl_file}...")
with open(pkl_file, "rb") as f:
    data = pickle.load(f)

# Extract features and labels
probe_features = data['probe_features']
gallery_features = data['gallery_features']
probe_lbls = np.asarray(data['probe_lbls'])
gallery_lbls = np.asarray(data['gallery_lbls'])

# Flatten embeddings if they have more than 2 dimensions
if len(probe_features.shape) > 2:
    probe_features = probe_features.reshape(probe_features.shape[0], -1)
if len(gallery_features.shape) > 2:
    gallery_features = gallery_features.reshape(gallery_features.shape[0], -1)

# Define the set of known vs unknown based on the same logic as evaluate_Gait3D
unique_test_ids = np.unique(np.concatenate([probe_lbls, gallery_lbls]))
num_intruders = int(len(unique_test_ids) * 0.10) # 10% intruders
known_ids = unique_test_ids[:-num_intruders]
is_known_probe = np.isin(probe_lbls, known_ids)

# Filter gallery to only include known IDs
gallery_known_mask = np.isin(gallery_lbls, known_ids)
gallery_known_features = gallery_features[gallery_known_mask]

results_summary = []

for n_comp in [256, 512]:
    print(f"\n" + "="*50)
    print(f"RUNNING GMM WITH {n_comp} COMPONENTS")
    print("="*50)
    
    gmm = GaussianMixture(n_components=n_comp, covariance_type='diag', random_state=42, verbose=1)
    gmm.fit(gallery_known_features)

    # Calculate scores (Log-Likelihood) for all probe samples
    print(f"Calculating log-likelihood scores for {n_comp} components...")
    probe_scores = gmm.score_samples(probe_features)

    # Evaluation: EER
    y_true = np.zeros(len(probe_scores))
    y_true[is_known_probe] = 1
    y_score = probe_scores 

    fpr, tpr, thresholds = roc_curve(y_true, y_score)
    fnr = 1 - tpr
    eer = fpr[np.nanargmin(np.absolute((fnr - fpr)))]
    results_summary.append((n_comp, eer))
    print(f"EER ({n_comp} components): {eer*100:.2f}%")

print("\n" + "="*50)
print("SUMMARY OF RESULTS")
print("="*50)
for n_comp, eer in results_summary:
    print(f"GMM {n_comp} components: EER = {eer*100:.2f}%")
print("="*50)
